#include <bits/stdc++.h>
using namespace std;

void apply_op(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-y-1] [n-y..n-1]
    vector<int> np;
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    // Place elements 1, 2, ..., n into positions 0, 1, ..., n-1
    for (int i = 0; i < n - 2 && (int)ops.size() < 4 * n; i++) {
        // Find where value (i+1) is
        int j = -1;
        for (int k = i; k < n; k++) if (p[k] == i + 1) { j = k; break; }
        if (j == i) continue; // already in place

        // Step 1: bring p[j] to position 0 if it's not there
        if (j > 0 && j < n - 1) {
            // x = j, y = n - 1 - j: valid since j > 0, n-1-j > 0, j + n-1-j = n-1 < n
            int x = j, y = n - 1 - j;
            ops.push_back({x, y});
            apply_op(p, x, y);
            j = 0;
        } else if (j == n - 1) {
            // x = 1, y = 1 (swap first and last, middle stays)
            // After: last goes to pos 0, first goes to pos n-1
            int x = n - 1, y = 1; // valid: n-1+1=n not < n... invalid
            // Use x=1, y=n-2: brings last n-2 to front? No.
            // x = j (=n-1), but x+y < n fails. Use x=1, y=1 first
            x = 1; y = 1;
            ops.push_back({x, y});
            apply_op(p, x, y);
            for (int k = i; k < n; k++) if (p[k] == i + 1) { j = k; break; }
            if (j > 0 && j < n - 1 && j != i) {
                ops.push_back({j, n - 1 - j});
                apply_op(p, j, n - 1 - j);
                j = 0;
            }
        }
        if (j == i) continue;
        // Now element is at position 0, need it at position i
        if (i > 0 && i < n - 1) {
            // x = n - i, y = i: swap suffix of length i with prefix of length n-i
            // Actually: x = n - i, y = i => x+y = n, not < n. 
            // Use x = 1, y = n - 1 - i
            int x = 1, y = n - 1 - i;
            if (x > 0 && y > 0 && x + y < n) {
                ops.push_back({x, y});
                apply_op(p, x, y);
            }
        }
    }

    printf("%d\n", (int)ops.size());
    for (auto& [a, b] : ops) printf("%d %d\n", a, b);
}
